import hashlib,json,subprocess
ROOT=Path('/home/andy/.codex/worktrees/table-parser-parity/sandbox-crypto')
HEAD='2601d8e607c731c5db479cc98bd5382b0eb44d62'
BASE='ec1faea226409e6481e2d883fd087231df877d9c'
PREFIX=Path('/tmp/revision-packages-future')
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True).strip()
def files(ref):return set(git('ls-tree','-r','--name-only',ref).splitlines())
def style(names):
 return {x for x in names if x.startswith(('packages/','scripts/','web/','.github/')) or x in {'pyproject.toml','uv.lock','.python-version','ruff.toml','pyrightconfig.json'}}
def extended(names):
 return style(names)|{x for x in names if x.startswith(('.agents/labs/','images/','examples/')) or x=='.gitignore'}
def pins(ref,names):
 result={}
 for name in sorted(names):
  data=subprocess.check_output(['git','show',ref+':'+name],cwd=ROOT)
  if ref==HEAD:assert (ROOT/name).read_bytes()==data,name
  result[name]={'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()}
 return result
